(5888994, 857885, 100335, '<td valign="top">This is a very common image and in order to really catch attention with it, it has to be impeccable. If its not perfect it will be scored even more harshly i''m afraid. I''ll rate this as if its the first time I''ve seen it thought.</td>', 'This is a very common image and in order to really catch attention with it, it has to be impeccable. If its not perfect it will be scored even more harshly i''m afraid. I''ll rate this as if its the first time I''ve seen it thought.', '2010-03-03 15:53:14.000000', NULL, 1),
(5888997, 856977, 100335, '<td valign="top">Nice but the lighting is uneven, the eggs on the left are much brighter than the ones on the right. Overall its nice and pleasing to the eye.</td>', 'Nice but the lighting is uneven, the eggs on the left are much brighter than the ones on the right. Overall its nice and pleasing to the eye.', '2010-03-03 15:55:28.000000', NULL, 1),
