(5891791, 858203, 811, '<td valign="top">great idea.  i like how the strings take you up and to the egg.</td>', 'great idea.  i like how the strings take you up and to the egg.', '2010-03-05 17:03:15.000000', NULL, 1),
(5891794, 858177, 811, '<td valign="top">Nice high key effect.  I find myself wanting to scoot it over to the left, just a hair though.</td>', 'Nice high key effect.  I find myself wanting to scoot it over to the left, just a hair though.', '2010-03-05 17:04:00.000000', NULL, 1),
