(5901712, 857105, 71244, '<td valign="top">HAHA. cute. good feedback too! keep enjoying the site!, hey, look, you got 2 10''s too, nice!</td>', 'HAHA. cute. good feedback too! keep enjoying the site!, hey, look, you got 2 10''s too, nice!', '2010-03-12 18:21:22.000000', NULL, 0),
(5901717, 857373, 76712, '<td valign="top">why six 1''s? i know its not that good but honestly six!?</td>', 'why six 1''s? i know its not that good but honestly six!?', '2010-03-12 18:27:47.000000', NULL, 0),
(5901980, 858090, 77196, '<td valign="top">Welcome to dpchallenge. Use the egg as inspiration - you have to develop a tough shell - lots of folks presume they know the intent, skill level, equipment, etc. of the photographer and vote (and comment) from that point of view. dpchallenge is a great place to grow and learn. If that is your desire, there are quite a few here who are willing to help. <br/>Perhaps this will help. I find your entry inspiring in that you have now entered more challenges than many who have been around for years and never gotten up the courage to enter. <br/>Looking forward to your next entry. <br/></td>', 'Welcome to dpchallenge. Use the egg as inspiration - you have to develop a tough shell - lots of folks presume they know the intent, skill level, equipment, etc. of the photographer and vote (and comment) from that point of view. dpchallenge is a great place to grow and learn. If that is your desire, there are quite a few here who are willing to help. Perhaps this will help. I find your entry inspiring in that you have now entered more challenges than many who have been around for years and never gotten up the courage to enter. Looking forward to your next entry. ', '2010-03-12 22:01:48.000000', NULL, 0),
(5902613, 858070, 70265, '<td valign="top">Belated congrats. This is the cutest concept ever!</td>', 'Belated congrats. This is the cutest concept ever!', '2010-03-13 14:17:24.000000', NULL, 0),
(5902867, 856615, 97225, '<td valign="top">Congratulations Lydia. This is so lovely - simple, elegant and beautifully done.</td>', 'Congratulations Lydia. This is so lovely - simple, elegant and beautifully done.', '2010-03-13 18:31:31.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5902910, 858004, 14476, '<td valign="top"><b>GREETINGS FROM THE CRITIQUE CLUB</b> <br/> <br/><img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=59029" rel="nofollow" target="_blank">Snaffles</a>!  We meet again.  That last one of yours was a winner, for sure.  This one?  Well, we all lay an egg once in a while. (Joking!Joking!)  Still, I think you and I both suffered from a similar fate in the Egg Challenge.  <br/> <br/>It may be that both of us suffered from the same malady:  "Record Shot."  <br/> <br/>Yep, I too, made a straight-on image of a good subject.  People pronounced it boring.  In your case, with an emu egg (big bruisers, aren''t they!) it would be good to shoot it high, low and at strange angles, just to see what would happen.  Probably something interesting would show up.  Then, while your lighting idea was excellent, ERM, that purple surface competes a bit with the texture of the egg as does the left-over glitter on that surface.  I think you get the idea that I''m suggesting different approaches to this perfectly fine subject matter.<br/> <br/>You are capable of it, and it would be fun to see the result.  Keep that emu egg.  No doubt there will be another Egg Challenge in our future!<br/> <br/>Alice<br/>:-))</td>', 'GREETINGS FROM THE CRITIQUE CLUB   Snaffles!  We meet again.  That last one of yours was a winner, for sure.  This one?  Well, we all lay an egg once in a while. (Joking!Joking!)  Still, I think you and I both suffered from a similar fate in the Egg Challenge.   It may be that both of us suffered from the same malady:  "Record Shot."   Yep, I too, made a straight-on image of a good subject.  People pronounced it boring.  In your case, with an emu egg (big bruisers, aren''t they!) it would be good to shoot it high, low and at strange angles, just to see what would happen.  Probably something interesting would show up.  Then, while your lighting idea was excellent, ERM, that purple surface competes a bit with the texture of the egg as does the left-over glitter on that surface.  I think you get the idea that I''m suggesting different approaches to this perfectly fine subject matter. You are capable of it, and it would be fun to see the result.  Keep that emu egg.  No doubt there will be another Egg Challenge in our future! Alice:-))', '2010-03-13 19:40:21.000000', NULL, 0),
(5903859, 858070, 81213, '<td valign="top">The egg is a little bright. Maybe its my screen but it blends in with the background too much for my taste...</td>', 'The egg is a little bright. Maybe its my screen but it blends in with the background too much for my taste...', '2010-03-14 15:19:50.000000', NULL, 0),
